          "path": ".github/workflows/pr-tests.yml",
          "action": "create"
        }
      ]
    }
  ],
  "notes": [
    "The workflow uses the standard GitHub Actions structure. It triggers on pull_request events. The job runs on ubuntu-latest, checks out code, sets up Node.js versions 20 and 22 using matrix strategy, installs dependencies, and runs npm test."
  ]
}

