{"new": "    it('should 415 on unknown encoding', function (done) {
      const test = request(this.server).post('/')
      test.set('Content-Encoding', 'nulls')
      test.set('Content-Type', 'application/octet-stream')
      test.write(Buffer.from('000000000000', 'hex'))
      test.expect(415, '[encoding.unsupported] unsupported content encoding "nulls"', done)
    })
  })

  describe('with rawBody option', function () {
    it('should set req.rawBody when true', function (done) {
      const server = createServer({ rawBody: true })

      request(server)
        .post('/')
        .set('Content-Type', 'application/octet-stream')
        .send('hello world')
        .expect(200, 'buf:68656c6c6f20776f726c64', function (err) {
          if (err) return done(err)
          assert.ok(server.rawBody !== undefined)
          assert.strictEqual(server.rawBody.toString(), 'hello world')
          done()
        })
    })

    it('should not set req.rawBody when false', function (done) {
      const server = createServer({ rawBody: false })

      request(server)
        .post('/')
        .set('Content-Type', 'application/octet-stream')
        .send('hello world')
        .expect(200, 'buf:68656c6c6f20776f726c64', function (err) {
          if (err) return done(err)
          assert.strictEqual(server.rawBody, undefined)
          done()
        })
    })

    it('should not set req.rawBody when missing', function (done) {
      const server = createServer()

      request(server)
        .post('/')
        .set('Content-Type', 'application/octet-stream')
        .send('hello world')
        .expect(200, 'buf:68656c6c6f20776f726c64', function (err) {
          if (err) return done(err)
          assert.strictEqual(server.rawBody, undefined)
          done()
        })
    })

    it('should set req.rawBody with gzip content-encoding', function (done) {
      const server = createServer({ rawBody: true })

      const test = request(server).post('/')
      test.set('Content-Encoding', 'gzip')
      test.set('Content-Type', 'application/octet-stream')
      test.write(Buffer.from('1f8b080000000000000003cb4f2e494d514f05007a6c0f330c000000', 'hex'))
      test.expect(200, 'buf:68656c6c6f20776f726c64', function (err) {
        if (err) return done(err)
        assert.ok(server.rawBody !== undefined)
        assert.strictEqual(server.rawBody.toString(), 'hello world')
        done()
      })
    })

    it('should work with verify option', function (done) {
      const server = createServer({
        rawBody: true,
        verify: function (req, res, buf) {
          if (buf[0] === 0x5b) throw new Error('no arrays')
        }
      })

      request(server)
        .post('/')
        .set('Content-Type', 'application/octet-stream')
        .send('hello world')
        .expect(200, 'buf:68656c6c6f20776f726c64', function (err) {
          if (err) return done(err)
          assert.ok(server.rawBody !== undefined)
          assert.strictEqual(server.rawBody.toString(), 'hello world')
          done()
        })
    })

    it('should set req.rawBody as Buffer', function (done) {
      const server = createServer({ rawBody: true })

      request(server)
        .post('/')
        .set('Content-Type', 'application/octet-stream')
        .send('hello world')
        .expect(200, 'buf:68656c6c6f20776f726c64', function (err) {
          if (err) return done(err)
          assert.ok(Buffer.isBuffer(server.rawBody))
          done()
        })
    })
  })
})
