{"new": "function createServer (opts) {
  const _bodyParser = typeof opts !== 'function'
    ? bodyParser.raw(opts)
    : opts

  const server = http.createServer(function (req, res) {
    _bodyParser(req, res, function (err) {
      if (err) {
        res.statusCode = err.status || 500
        res.end('[' + err.type + '] ' + err.message)
        return
      }

      if (Buffer.isBuffer(req.body)) {
        res.end('buf:' + req.body.toString('hex'))
        return
      }

      res.end(JSON.stringify(req.body) || typeof req.body)
    })
  })

  // Capture rawBody for test assertions
  const originalHandler = server.listeners('request')[0]
  server.removeAllListeners('request')
  server.on('request', function (req, res) {
    const originalEnd = res.end.bind(res)
    res.end = function (...args) {
      server.rawBody = req.rawBody
      return originalEnd(...args)
    }
    originalHandler(req, res)
  })

  return server
}", "old": "function createServer (opts) {
  const _bodyParser = typeof opts !== 'function'
    ? bodyParser.raw(opts)
    : opts

  return http.createServer(function (req, res) {
    _bodyParser(req, res, function (err) {
      if (err) {
        res.statusCode = err.status || 500
        res.end('[' + err.type + '] ' + err.message)
        return
      }

      if (Buffer.isBuffer(req.body)) {
        res.end('buf:' + req.body.toString('hex'))
        return
      }

      res.end(JSON.stringify(req.body) || typeof req.body)
    })
  })
}", "path": "test/raw.js"}

