'use strict'
const http = require('node:http')
const zlib = require('node:zlib')
const assert = require('node:assert')
const request = require('supertest')
const bodyParser = require('/tmp/repo/index.js')

function server (parser, opts) {
  const mw = parser(opts)
  return http.createServer((req, res) => {
    mw(req, res, (err) => {
      if (err) {
        res.statusCode = err.status || 500
        res.end('ERR:' + err.type + ':' + err.message + ':raw=' + (req.rawBody ? req.rawBody.toString('hex') : 'unset'))
        return
      }
      res.end(JSON.stringify({
        body: req.body,
        raw: req.rawBody ? req.rawBody.toString('hex') : 'unset',
        isBuf: Buffer.isBuffer(req.rawBody)
      }))
    })
  })
}

const latin1 = Buffer.from('6e616d6520697320e8aeba', 'hex')

async function main () {
  // 1. json, latin1 charset, rawBody true
  let res = await request(server(bodyParser.json, { rawBody: true }))
    .post('/').set('Content-Type', 'application/json; charset=iso-8859-1').write(latin1)
  console.log('json latin1:', res.text)
  let j = JSON.parse(res.text)
  assert.strictEqual(j.raw, latin1.toString('hex'))
  assert.strictEqual(j.isBuf, true)
  assert.strictEqual(j.body, 'name is è®º')

  // 2. gzip + rawBody true -> decompressed bytes
  const gz = zlib.gzipSync(Buffer.from('{"a":1}'))
  res = await request(server(bodyParser.json, { rawBody: true }))
    .post('/').set('Content-Type', 'application/json').set('Content-Encoding', 'gzip').write(gz)
  console.log('json gzip:', res.text)
  j = JSON.parse(res.text)
  assert.strictEqual(j.raw, Buffer.from('{"a":1}').toString('hex'))
  assert.deepStrictEqual(j.body, { a: 1 })

  // 3. rawBody not true -> unset
  for (const opts of [{}, { rawBody: false }, { rawBody: 'yes' }, { rawBody: 1 }]) {
    res = await request(server(bodyParser.json, opts))
      .post('/').set('Content-Type', 'application/json').send('{"a":1}')
    assert.strictEqual(JSON.parse(res.text).raw, 'unset', 'opts ' + JSON.stringify(opts))
  }
  console.log('not-true variants: unset ok')

  // 4. rawBody + verify together
  let seen
  res = await request(server(bodyParser.json, {
    rawBody: true,
    verify: (req, r, buf, enc) => { seen = { hex: buf.toString('hex'), enc } }
  })).post('/').set('Content-Type', 'application/json; charset=iso-8859-1').write(latin1)
  j = JSON.parse(res.text)
  assert.strictEqual(seen.hex, latin1.toString('hex'))
  assert.strictEqual(seen.enc, 'iso-8859-1')
  assert.strictEqual(j.raw, latin1.toString('hex'))
  console.log('verify+rawBody ok')

  // 5. rawBody still there when parse fails
  res = await request(server(bodyParser.json, { rawBody: true }))
    .post('/').set('Content-Type', 'application/json').send('{bad')
  console.log('parse fail:', res.status, res.text)
  assert.strictEqual(res.status, 400)
  assert.ok(res.text.includes('raw=' + Buffer.from('{bad').toString('hex')))

  // 6. text parser
  res = await request(server(bodyParser.text, { rawBody: true }))
    .post('/').set('Content-Type', 'text/plain; charset=iso-8859-1').write(latin1)
  j = JSON.parse(res.text)
  assert.strictEqual(j.raw, latin1.toString('hex'))
  assert.strictEqual(j.body, 'name is è®º')
  console.log('text ok')

  // 7. urlencoded parser
  res = await request(server(bodyParser.urlencoded, { rawBody: true, extended: false }))
    .post('/').set('Content-Type', 'application/x-www-form-urlencoded').send('a=1&b=2')
  j = JSON.parse(res.text)
  assert.strictEqual(j.raw, Buffer.from('a=1&b=2').toString('hex'))
  assert.deepStrictEqual(j.body, { a: '1', b: '2' })
  console.log('urlencoded ok')

  // 8. raw parser
  res = await request(server(bodyParser.raw, { rawBody: true }))
    .post('/').set('Content-Type', 'application/octet-stream').write(Buffer.from('000102', 'hex'))
  j = JSON.parse(res.text)
  assert.strictEqual(j.raw, '000102')
  assert.strictEqual(j.body.toString('hex'), '000102')
  console.log('raw ok')

  // 9. no body / unmatched type -> rawBody unset
  res = await request(server(bodyParser.json, { rawBody: true })).get('/')
  assert.strictEqual(JSON.parse(res.text).raw, 'unset')
  res = await request(server(bodyParser.json, { rawBody: true }))
    .post('/').set('Content-Type', 'text/plain').send('hi')
  assert.strictEqual(JSON.parse(res.text).raw, 'unset')
  console.log('no body / unmatched type ok')

  console.log('ALL PASS')
}
main().catch((e) => { console.error(e); process.exit(1) })
