  var res = this.res;
  // Check for API clients preference (e.g., Accept header)
  var acceptHeader = res.getHeader('Accept');
  var apiClients = ['application/json', 'application/vnd.api'];

  var respondJson404 = function(path) {
    res.status(404).type('application/json').send({
      error: 'Not Found',
      path: path,
      statusCode: 404
    });
  };

  if (apiClients.some(apiType => acceptHeader && acceptHeader.includes(apiType))) {
    // Handle 404 as JSON
    // ... somehow call the 404 response here
  } else {
    // Fallback to original logic (or just let finalhandler do its thing if I can't replace it entirely)
