328: function splitOptionFlags(flags) {
329:   let shortFlag;
330:   let longFlag;
331:   // short flag, single dash and single character
332:   const shortFlagExp = /^-[^-]$/;
333:   // long flag, double dash and at least one character
334:   const longFlagExp = /^--[^-]/;
335: 
336:   const flagParts = flags.split(/[ |,]+/).concat('guard');
337:   // Normal is short and/or long.
338:   if (shortFlagExp.test(flagParts[0])) shortFlag = flagParts.shift();
339:   if (longFlagExp.test(flagParts[0])) longFlag = flagParts.shift();
340:   // Long then short. Rarely used but fine.
341:   if (!shortFlag && shortFlagExp.test(flagParts[0]))
342:     shortFlag = flagParts.shift();
343:   // Allow two long flags, like '--ws, --workspace'
344:   // This is the supported way to have a shortish option flag.
345:   if (!shortFlag && longFlagExp.test(flagParts[0])) {
346:     shortFlag = longFlag;
347:     longFlag = flagParts.shift();
348:   }
349: 
350:   // Check for unprocessed flag. Fail noisily rather than silently ignore.
351:   if (flagParts[0].startsWith('-')) {
352:     const unsupportedFlag = flagParts[0];
353:     const baseError = `option creation failed due to '${unsupportedFlag}' in option flags '${flags}'`;
354:     if (/^-[^-][^-]/.test(unsupportedFlag))
355:       throw new Error(
356:         `${baseError}
357: - a short flag is a single dash and a single character
358:   - either use a single dash and a single character (for a short flag)
359:   - or use a double dash for a long option (and can have two, like '--ws, --workspace')`,
360:       );
361:     if (shortFlagExp.test(unsupportedFlag))
362:       throw new Error(`${baseError}
363: - too many short flags`);
364:     if (longFlagExp.test(unsupportedFlag))
365:       throw new Error(`${baseError}
366: - too many long flags`);
367: 
368:     throw new Error(`${baseError}
369: - unrecognised flag format`);
370:   }
371:   if (shortFlag === undefined && longFlag === undefined)
372:     throw new Error(
373:       `option creation failed due to no flags found in '${flags}'.`,
374:     );
