import * as commander from '../index.js';
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

class CustomOption extends commander.Option {
  storageKey() {
    return 'custom_' + super.storageKey();
  }
}

describe('Option#storageKey', () => {
  test('attributeName is deprecated alias for storageKey', () => {
    const option = new commander.Option('--foo-bar');
    assert.equal(option.storageKey(), 'fooBar');
    assert.equal(option.attributeName(), 'fooBar');
  });

  test('subclass storageKey used for cli value', () => {
    const program = new commander.Command();
    program.addOption(new CustomOption('--foo-bar'));
    program.parse(['node', 'test', '--foo-bar']);
    assert.equal(program.opts().custom_fooBar, true);
  });

  test('subclass storageKey used for default value', () => {
    const program = new commander.Command();
    program.addOption(new CustomOption('--foo-bar').default('defaultValue'));
    program.parse(['node', 'test']);
    assert.equal(program.opts().custom_fooBar, 'defaultValue');
  });

  test('subclass storageKey used for env value', () => {
    process.env.CUSTOM_FOO = 'envValue';
    const program = new commander.Command();
    program.addOption(new CustomOption('--foo-bar <value>').env('CUSTOM_FOO'));
    program.parse(['node', 'test']);
    assert.equal(program.opts().custom_fooBar, 'envValue');
    delete process.env.CUSTOM_FOO;
  });

  test('subclass storageKey used for negated option', () => {
    const program = new commander.Command();
    program.addOption(new CustomOption('--no-foo-bar'));
    program.parse(['node', 'test', '--no-foo-bar']);
    assert.equal(program.opts().custom_fooBar, false);
  });
});
