356:         `${baseError}
357: - a short flag is a single dash and a single character
358:   - either use a single dash and a single character (for a short flag)
359:   - or use a double dash for a long option (and can have two, like '--ws, --workspace')`,
360:       );
361:     if (shortFlagExp.test(unsupportedFlag))
362:       throw new Error(`${baseError}
363: - too many short flags`);
364:     if (longFlagExp.test(unsupportedFlag))
