328: function splitOptionFlags(flags) {
329:   let shortFlag;
330:   let longFlag;
331:   // short flag, single dash and single character
332:   const shortFlagExp = /^-[^-]$/;
333:   // long flag, double dash and at least one character
334:   const longFlagExp = /^--[^-]/;
335: 
336:   const flagParts = flags.split(/[ |,]+/).concat('guard');
337:   // Normal is short and/or long.
338:   if (shortFlagExp.test(flagParts[0])) shortFlag = flagParts.shift();
339:   if (longFlagExp.test(flagParts[0])) longFlag = flagParts.shift();
340:   // Long then short. Rarely used but fine.
341:   if (!shortFlag && shortFlagExp.test(flagParts[0]))
342:     shortFlag = flagParts.shift();
343:   // Allow two long flags, like '--ws, --workspace'
344:   // This is the supported way to have a shortish option flag.
345:   if (!shortFlag && longFlagExp.test(flagParts[0])) {
346:     shortFlag = longFlag;
347:     longFlag = flagParts.shift();
