{"path": "tests/options.storageKey.test.js", "content": "import * as commander from '../index.js';
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

describe('option storageKey', () => {
  test('when option defined with --word-word then storageKey is wordWord', () => {
    const option = new commander.Option('--my-option');
    assert.equal(option.storageKey(), 'myOption');
  });

  test('when option defined with --no-word-word then storageKey is wordWord', () => {
    const option = new commander.Option('--no-my-option');
    assert.equal(option.storageKey(), 'myOption');
  });

  test('when attributeName called then returns storageKey', () => {
    const option = new commander.Option('--my-option');
    assert.equal(option.attributeName(), option.storageKey());
  });

  test('when storageKey overridden then used for cli, default, env and negated option', () => {
    class CustomOption extends commander.Option {
      storageKey() {
        return `custom_${this.name()}`;
      }
    }

    const program = new commander.Command();
    program.addOption(new CustomOption('--foo <value>').default('default'));
    program.addOption(new CustomOption('--bar <value>').env('BAR'));
    program.addOption(new CustomOption('--no-baz'));
    process.env.BAR = 'from-env';
    program.parse(['--foo', 'from-cli'], { from: 'user' });

    assert.deepEqual(program.opts(), {
      custom_foo: 'from-cli',
      custom_bar: 'from-env',
      custom_no-baz: true,
    });
    assert.equal(program.getOptionValueSource('custom_foo'), 'cli');
    assert.equal(program.getOptionValueSource('custom_bar'), 'env');
    assert.equal(program.getOptionValueSource('custom_no-baz'), 'default');
  });
});
"}

