  _applyEnvPrefix(option) {
    if (this._envPrefix === undefined) return;
    if (option.negate) return;
    // An environment variable set using .env() wins over the prefix.
    if (option.envVar !== undefined && !option._envVarFromPrefix) return;
    option.envVar =
