  /**
   * Set a prefix for environment variables used to supply option values.
   *
   * After calling this, every option of the command which does not have its own
   * environment variable set using `.env()` reads its value from an environment
   * variable named the prefix followed by the option name in UPPER_SNAKE_CASE.
   * This applies to options added before or after the call.
   *
   * Negated options (like `--no-color`) do not get an environment variable.
   *
   * @example
   * program.envPrefix('MYAPP_').option('--dry-run');
   * // reads MYAPP_DRY_RUN
   *
   * @param {string} prefix
   * @return {Command} `this` command for chaining
   */

  envPrefix(prefix) {
    this._envPrefix = prefix;
    this.options.forEach((option) => this._applyEnvPrefix(option));
    return this;
  }

  /**
   * Set the environment variable for an option from the command prefix, if applicable.
   *
   * @param {Option} option
   * @private
   */

  _applyEnvPrefix(option) {
    if (this._envPrefix === undefined) return;
    if (option.negate) return;
    // An environment variable set using .env() wins over the prefix.
    if (option.envVar !== undefined && !option._envVarFromPrefix) return;
    option.envVar =
      this._envPrefix + option.name().replace(/-/g, '_').toUpperCase();
    option._envVarFromPrefix = true;
  }"}

