{"path":"tests/options.envPrefix.test.js","content":"import * as commander from '../index.js';
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

describe('Command.envPrefix()', () => {
  test('when call .envPrefix() then returns this', () => {
    const program = new commander.Command();
    const result = program.envPrefix('MYAPP_');
    assert.equal(result, program);
  });

  test('when option added after prefix then value from env', () => {
    const program = new commander.Command();
    process.env.MYAPP_DRY_RUN = 'anything';
    program.envPrefix('MYAPP_').option('--dry-run');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().dryRun, true);
    delete process.env.MYAPP_DRY_RUN;
  });

  test('when option added before prefix then value from env', () => {
    const program = new commander.Command();
    process.env.MYAPP_DRY_RUN = 'anything';
    program.option('--dry-run').envPrefix('MYAPP_');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().dryRun, true);
    delete process.env.MYAPP_DRY_RUN;
  });

  test('when option takes value then value from env', () => {
    const program = new commander.Command();
    process.env.MYAPP_LOG_LEVEL = 'debug';
    program.envPrefix('MYAPP_').option('--log-level <level>');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().logLevel, 'debug');
    delete process.env.MYAPP_LOG_LEVEL;
  });

  test('when env and cli then value from cli', () => {
    const program = new commander.Command();
    process.env.MYAPP_LOG_LEVEL = 'env';
    program.envPrefix('MYAPP_').option('--log-level <level>');
    program.parse(['--log-level', 'cli'], { from: 'user' });
    assert.equal(program.opts().logLevel, 'cli');
    delete process.env.MYAPP_LOG_LEVEL;
  });

  test('when env and default then value from env', () => {
    const program = new commander.Command();
    process.env.MYAPP_LOG_LEVEL = 'env';
    program.envPrefix('MYAPP_').option('--log-level <level>', 'level', 'default');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().logLevel, 'env');
    delete process.env.MYAPP_LOG_LEVEL;
  });

  test('when no env and no cli then value from default', () => {
    const program = new commander.Command();
    program.envPrefix('MYAPP_').option('--log-level <level>', 'level', 'default');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().logLevel, 'default');
  });

  test('when option has own .env() then own env wins over prefix', () => {
    const program = new commander.Command();
    process.env.MYAPP_LOG_LEVEL = 'prefix';
    process.env.OWN_LOG_LEVEL = 'own';
    program
      .envPrefix('MYAPP_')
      .addOption(new commander.Option('--log-level <level>').env('OWN_LOG_LEVEL'));
    program.parse([], { from: 'user' });
    assert.equal(program.opts().logLevel, 'own');
    delete process.env.MYAPP_LOG_LEVEL;
    delete process.env.OWN_LOG_LEVEL;
  });

  test('when option has own .env() added before prefix then own env wins', () => {
    const program = new commander.Command();
    process.env.MYAPP_LOG_LEVEL = 'prefix';
    process.env.OWN_LOG_LEVEL = 'own';
    program
      .addOption(new commander.Option('--log-level <level>').env('OWN_LOG_LEVEL'))
      .envPrefix('MYAPP_');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().logLevel, 'own');
    delete process.env.MYAPP_LOG_LEVEL;
    delete process.env.OWN_LOG_LEVEL;
  });

  test('when negated option then no env variable', () => {
    const program = new commander.Command();
    process.env.MYAPP_COLOR = 'anything';
    program.envPrefix('MYAPP_').option('--no-color');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().color, undefined);
    delete process.env.MYAPP_COLOR;
  });

  test('when option name has dashes then env variable uses underscores', () => {
    const program = new commander.Command();
    process.env.MYAPP_DRY_RUN = 'anything';
    program.envPrefix('MYAPP_').option('--dry-run');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().dryRun, true);
    delete process.env.MYAPP_DRY_RUN;
  });

  test('when help then shows env variable', () => {
    const program = new commander.Command();
    program.envPrefix('MYAPP_').option('--dry-run', 'do not make changes');
    const helpInformation = program.helpInformation();
    assert.match(helpInformation, /env: MYAPP_DRY_RUN/);
  });

  test('when custom argParser then env value is parsed', () => {
    const program = new commander.Command();
    process.env.MYAPP_COUNT = '42';
    program
      .envPrefix('MYAPP_')
      .addOption(
        new commander.Option('--count <number>').argParser((value) =>
          parseInt(value, 10),
        ),
      );
    program.parse([], { from: 'user' });
    assert.equal(program.opts().count, 42);
    delete process.env.MYAPP_COUNT;
  });

  test('when envPrefix called twice then latest prefix used', () => {
    const program = new commander.Command();
    process.env.SECOND_DRY_RUN = 'anything';
    program.envPrefix('FIRST_').option('--dry-run').envPrefix('SECOND_');
    program.parse([], { from: 'user' });
    assert.equal(program.opts().dryRun, true);
    delete process.env.SECOND_DRY_RUN;
  });
});
"}

