import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

function makeProgram() {
  const program = new commander.Command();
  const warnings = [];
  program.configureOutput({
    writeOut: () => {},
    writeErr: (str) => warnings.push(str),
  });
  return { program, warnings };
}

describe('Option.deprecated()', () => {
  test('when deprecated option used then warning with message', () => {
    const { program, warnings } = makeProgram();
    program.addOption(
      new commander.Option('--old-name <value>').deprecated('use --new-name'),
    );
    program.parse(['--old-name', 'x'], { from: 'user' });
    assert.deepEqual(warnings, [
      "warning: option '--old-name <value>' is deprecated: use --new-name\n",
    ]);
  });

  test('when deprecated option used without message then warning without message', () => {
    const { program, warnings } = makeProgram();
    program.addOption(new commander.Option('--old-name <value>').deprecated());
    program.parse(['--old-name', 'x'], { from: 'user' });
    assert.deepEqual(warnings, [
      "warning: option '--old-name <value>' is deprecated\n",
    ]);
  });

  test('when deprecated option used then option still works', () => {
    const { program } = makeProgram();
    program.addOption(new commander.Option('--old-name <value>').deprecated());
    program.parse(['--old-name', 'x'], { from: 'user' });
    assert.equal(program.opts().oldName, 'x');
  });

  test('when deprecated option used then action still called', () => {
    const { program } = makeProgram();
    let called = false;
    program
      .addOption(new commander.Option('--old-name <value>').deprecated())
      .action(() => {
        called = true;
      });
    program.parse(['--old-name', 'x'], { from: 'user' });
    assert.equal(called, true);
  });

  test('when deprecated option used twice then one warning', () => {
    const { program, warnings } = makeProgram();
    program.addOption(
      new commander.Option('--old-name <value>').deprecated('old'),
    );
    program.parse(['--old-name', 'x', '--old-name', 'y'], { from: 'user' });
    assert.equal(warnings.length, 1);
  });

  test('when deprecated option not used then no warning', () => {
    const { program, warnings } = makeProgram();
    program.addOption(new commander.Option('--old-name <value>').deprecated());
    program.parse([], { from: 'user' });
    assert.deepEqual(warnings, []);
  });

  test('when deprecated option value from default then no warning', () => {
