import * as React from 'react';

import { cn } from '@/utils/cn';

const badgeVariants = cva(
  'inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium',
  {
    variants: {
      variant: {
        default: 'bg-gray-100 text-gray-800',
        success: 'bg-green-100 text-green-800',
        warning: 'bg-amber-100 text-amber-800',
        danger: 'bg-red-100 text-red-800',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  },
);

export type BadgeProps = React.HTMLAttributes<HTMLSpanElement> &
  VariantProps<typeof badgeVariants>;

const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(
  ({ className, variant = 'default', ...props }, ref) => {
    return (
      <span
        ref={ref}
        role="status"
        data-variant={variant}
        className={cn(badgeVariants({ variant, className }))}
        {...props}
      />
    );
  },
);
Badge.displayName = 'Badge';

export { Badge, badgeVariants };
"}

{"path": "src/components/ui/badge/__tests__/badge.test.tsx", "content": "import { Badge } from '@/components/ui/badge';
import { rtlRender, screen } from '@/testing/test-utils';

test('renders a status pill with the given variant', () => {
  rtlRender(<Badge variant="success">Active</Badge>);

  const badge = screen.getByRole('status');

  expect(badge).toHaveTextContent('Active');
  expect(badge).toHaveAttribute('data-variant', 'success');
  expect(badge).toHaveClass('bg-green-100', 'text-green-800');
});

test('defaults to the default variant', () => {
  rtlRender(<Badge>New</Badge>);

  const badge = screen.getByRole('status');

  expect(badge).toHaveAttribute('data-variant', 'default');
  expect(badge).toHaveClass('bg-gray-100', 'text-gray-800');
});

test('className wins over a conflicting default class', () => {
  rtlRender(<Badge className="bg-blue-100">New</Badge>);

  const badge = screen.getByRole('status');

  expect(badge).toHaveClass('bg-blue-100');
  expect(badge).not.toHaveClass('bg-gray-100');
});
"}

