function server (parser) {
  return http.createServer(function (req, res) {
    parser(req, res, function (err) {
      if (err) {
        res.statusCode = err.status || 500
        res.end('ERR:' + err.type + ':' + (req.rawBody ? req.rawBody.toString('hex') : 'none'))
      } else {
        res.statusCode = 200
        res.end('raw:' + (req.rawBody ? req.rawBody.toString('hex') : 'none') +
          '|body:' + (Buffer.isBuffer(req.body) ? req.body.toString('hex') : JSON.stringify(req.body)))
      }
    })
  })
}

async function main () {
  // json rawBody true
  let r = await request(server(bodyParser.json({ rawBody: true })))
    .post('/').set('Content-Type', 'application/json').send('{"a":1}')
  console.log('json rawBody:', r.text)

  // json rawBody missing
  r = await request(server(bodyParser.json()))
    .post('/').set('Content-Type', 'application/json').send('{"a":1}')
  console.log('json default:', r.text)

  // json rawBody false
  r = await request(server(bodyParser.json({ rawBody: false })))
    .post('/').set('Content-Type', 'application/json').send('{"a":1}')
  console.log('json false:', r.text)

  // gzip
  const gz = zlib.gzipSync(Buffer.from('{"a":1}'))
  r = await request(server(bodyParser.json({ rawBody: true })))
    .post('/').set('Content-Type', 'application/json').set('Content-Encoding', 'gzip').send(gz)
  console.log('json gzip:', r.text)

  // latin1 text
  r = await request(server(bodyParser.text({ rawBody: true })))
    .post('/').set('Content-Type', 'text/plain; charset=latin1').send(Buffer.from([0xe9, 0x20, 0x61]))
  console.log('text latin1:', r.text)

  // urlencoded
  r = await request(server(bodyParser.urlencoded({ rawBody: true })))
    .post('/').set('Content-Type', 'application/x-www-form-urlencoded').send('a=b&c=d')
  console.log('urlencoded:', r.text)

  // raw
  r = await request(server(bodyParser.raw({ rawBody: true })))
    .post('/').set('Content-Type', 'application/octet-stream').send('hello')
  console.log('raw:', r.text)

  // verify + rawBody
  r = await request(server(bodyParser.json({ rawBody: true, verify: function (req, res, buf) { if (buf[0] === 0x5b) throw new Error('no arrays') } })))
    .post('/').set('Content-Type', 'application/json').send('["x"]')
  console.log('verify fail:', r.text)

  // parse failure
  r = await request(server(bodyParser.json({ rawBody: true })))
    .post('/').set('Content-Type', 'application/json').send('{bad')
  console.log('parse fail:', r.text)
}
main().catch(e => { console.error(e); process.exit(1) })
