21:     d[0][j] = j;
22:   }
23: 
24:   // fill matrix
25:   for (let j = 1; j <= b.length; j++) {
26:     for (let i = 1; i <= a.length; i++) {
27:       let cost;
28:       if (a[i - 1] === b[j - 1]) {
29:         cost = 0;
30:       } else {
31:         cost = 1;
32:       }
33:       d[i][j] = Math.min(
34:         d[i - 1][j] + 1, // deletion
