3: function editDistance(a, b) {
4:   // https://en.wikipedia.org/wiki/Damerau–Levenshtein_distance
5:   // Calculating optimal string alignment distance, no substring is edited more than once.
6:   // (Simple implementation.)
7: 
8:   // Quick early exit, return worst case.
9:   if (Math.abs(a.length - b.length) > maxDistance)
10:     return Math.max(a.length, b.length);
11: 
12:   // distance between prefix substrings of a and b
13:   const d = [];
14: 
15:   // pure deletions turn a into empty string
16:   for (let i = 0; i <= a.length; i++) {
17:     d[i] = [i];
18:   }
19:   // pure insertions turn empty string into b
20:   for (let j = 0; j <= b.length; j++) {
21:     d[0][j] = j;
22:   }
23: 
24:   // fill matrix
25:   for (let j = 1; j <= b.length; j++) {
26:     for (let i = 1; i <= a.length; i++) {
27:       let cost;
28:       if (a[i - 1] === b[j - 1]) {
29:         cost = 0;
30:       } else {
31:         cost = 1;
32:       }
33:       d[i][j] = Math.min(
34:         d[i - 1][j] + 1, // deletion
35:         d[i][j - 1] + 1, // insertion
36:         d[i - 1][j - 1] + cost, // substitution
37:       );
38:     }
39:   }
40: 
41:   return d[a.length][b.length];
42: }
43: 
44: /**
45:  * Find close matches, restricted to same number of edits.
46:  *
47:  * @param {string} word
48:  * @param {string[]} candidates
49:  * @returns {string}
50:  */
51: 
52: export function suggestSimilar(word, candidates) {
53:   if (!candidates || candidates.length === 0) return '';
54:   // remove possible duplicates
55:   candidates = Array.from(new Set(candidates));
56: 
57:   const searchingOptions = word.startsWith('--');
58:   if (searchingOptions) {
59:     word = word.slice(2);
60:     candidates = candidates.map((candidate) => candidate.slice(2));
61:   }
62: 
63:   let similar = [];
64:   let bestDistance = maxDistance;
65:   const minSimilarity = 0.4;
66:   candidates.forEach((candidate) => {
67:     if (candidate.length <= 1) return; // no one character guesses
68: 
69:     const distance = editDistance(word, candidate);
70:     const length = Math.max(word.length, candidate.length);
71:     const similarity = (length - distance) / length;
72:     if (similarity > minSimilarity) {
73:       if (distance < bestDistance) {
74:         // better edit distance, throw away previous worse matches
75:         bestDistance = distance;
76:         similar = [candidate];
77:       } else if (distance === bestDistance) {
78:         similar.push(candidate);
79:       }
80:     }
81:   });
82: 
83:   similar.sort((a, b) => a.localeCompare(b));
84:   if (searchingOptions) {
85:     similar = similar.map((candidate) => `--${candidate}`);
86:   }
87: 
88:   if (similar.length > 1) {
89:     return `\n(Did you mean one of ${similar.join(', ')}?)`;
90:   }
91:   if (similar.length === 1) {
92:     return `\n(Did you mean ${similar[0]}?)`;
93:   }
94:   return '';
95: }
