import assert from 'node:assert/strict';
import { Command } from '../index.js';

// Two swapped neighbouring letters are a single edit (transposition),
// so should still get a "Did you mean" suggestion.

function getSuggestion(program, arg) {
  let message = '';
  program
    .showSuggestionAfterError() // make sure on
    .exitOverride()
    .configureOutput({
      writeErr: (str) => {
        message = str;
      },
    });

  try {
    program.parse([arg], { from: 'user' });
  } catch (err) {
    /* empty */
  }

  const match = message.match(/Did you mean (one of )?(.*)\?/);
  return match ? match[2] : null;
}

describe('suggestSimilar transposition', () => {
  test('when command name has two swapped letters then suggest command', () => {
    const program = new Command();
    program.command('ls');
    const suggestion = getSuggestion(program, 'sl');
    assert.equal(suggestion, 'ls');
  });

  test('when option name has two swapped letters then suggest option', () => {
    const program = new Command();
    program.option('--dry');
    const suggestion = getSuggestion(program, '--dyr');
    assert.equal(suggestion, '--dry');
  });
});
