function stringifySorted (value, replacer, spaces) {
  // run the value through JSON.stringify once so that a function replacer
  // (and any toJSON) is applied before the keys are sorted
  var applied = JSON.stringify(value, replacer)

  if (typeof applied !== 'string') {
    // JSON.stringify returns undefined for values like undefined and functions
    return applied
  }

