{"why": "Probe originalUrl for mounted apps at the finalhandler stage and Accept negotiation edge cases", "cmd": "cat > /tmp/probe.js <<'EOF'
const express = require('./');
const request = require('supertest');

const app = express();
const sub = express();
sub.get('/ok', (req, res) => res.send('ok'));
app.use('/api', sub);
const orig = express.application.handle;
request(app).get('/api/nope?q=1').set('Accept', 'application/json').end((e, r) => {
  console.log('mounted 404:', r.status, r.headers['content-type']);
});

// inspect what the outermost finalhandler sees
const app2 = express();
app2.use('/api', (req, res, next) => {
  console.log('mounted mw originalUrl=', req.originalUrl, 'url=', req.url, 'baseUrl=', req.baseUrl);
  next();
});
app2.use((err, req, res, next) => next(err));
request(app2).get('/api/deep/nope?x=1').end((e, r) => {
  console.log('plain mounted 404 status', r.status);
});

// accept negotiation matrix
const cases = ['application/json', 'text/html', '*/*', undefined, 'application/json;q=0.5,text/html', 'foo/bar', 'text/plain'];
let i = 0;
function nextCase() {
  if (i >= cases.length) return;
  const a = cases[i++];
  const a3 = express();
  a3.use((req, res, next) => {
    console.log(JSON.stringify(a), '->', req.accepts(['html', 'json']));
    next();
  });
  const req = request(a3).get('/z');
  if (a) req.set('Accept', a);
  req.end(() => nextCase());
}
nextCase();
EOF
node /tmp/probe.js"}

