/**
 * Wrap a final callback to respond with a JSON body for
 * not-found requests from clients that prefer JSON.
 *
 * @param {IncomingMessage} req
 * @param {ServerResponse} res
 * @param {Function} done
 * @return {Function}
 * @private
 */

function jsonNotFound(req, res, done) {
  return function (err) {
    if (err || res.headersSent) {
      return done(err);
    }

    if (req.accepts(['html', 'json']) !== 'json') {
      return done(err);
    }

    var path;

    try {
      path = parseUrl.original(req).pathname;
    } catch (e) {
      path = req.url || '/';
    }

    res.statusCode = 404;
    res.json({
      error: 'Not Found',
      method: req.method,
      path: path
    });
  };
}
