```js
function jsonNotFound(req, res, done) {
  return function (err) {
    // errors and requests that prefer HTML keep the default handling
    if (err || res.headersSent || req.method === 'HEAD' || req.accepts(['html', 'json']) !== 'json') {
      return done(err);
    }

    var path = parseUrl.original(req).pathname;

    res.statusCode = 404;
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    var body = JSON.stringify({ error: 'Not Found', method: req.method, path: path });
    res.setHeader('Content-Length', Buffer.byteLength(body, 'utf8'));
    res.end(body, 'utf8');
  };
}
```

