});

// accept negotiation matrix
const cases = ['application/json', 'text/html', '*/*', undefined, 'application/json;q=0.5,text/html', 'foo/bar', 'text/plain'];
let i = 0;
function nextCase() {
  if (i >= cases.length) return;
  const a = cases[i++];
  const a3 = express();
  a3.use((req, res, next) => {
    console.log(JSON.stringify(a), '->', req.accepts(['html', 'json']));
    next();
  });
  const req = request(a3).get('/z');
  if (a) req.set('Accept', a);
  req.end(() => nextCase());
}
nextCase();
