      request(express())
      .post('/missing/thing?a=b')
      .set('Accept', 'application/json')
      .expect(404)
      .expect({ error: 'Not Found', method: 'POST', path: '/missing/thing' }, done);
    })

    it('should respond with the full path in a mounted app', function(done){
