      var sub = express();

      sub.get('/ok', function (req, res) { res.send('ok') });
      app.use('/api', sub);

      request(app)
      .get('/api/missing?q=1')
      .set('Accept', 'application/json')
      .expect(404)
      .expect({ error: 'Not Found', method: 'GET', path: '/api/missing' }, done);
    })

    it('should not respond with a body for HEAD', function(done){
      request(express())
      .head('/missing')
      .set('Accept', 'application/json')
      .expect(404)
      .expect('Content-Type', 'application/json; charset=utf-8')
      .expect('', done);
    })
  })

  describe('when the client prefers html', function () {
    it('should respond with an html body', function(done){
