      request(express())
      .get('/missing')
      .expect(404)
      .expect('Content-Type', 'text/html; charset=utf-8', done);
    })
  })

  describe('when a route errors', function () {
    it('should not change the error response', function(done){
      var app = express();

      app.get('/boom', function (req, res, next) { next(new Error('kaboom')) });

      request(app)
      .get('/boom')
      .set('Accept', 'application/json')
      .expect(500, done);
    })
  })
