128:   var encoding;
129:   var req = this.req;
130: 
131:   // settings
132:   var app = this.app;
133: 
134:   switch (typeof chunk) {
135:     // string defaulting to html
136:     case 'string':
137:       encoding = 'utf8';
138:       const type = this.get('Content-Type');
139: 
140:       if (typeof type === 'string') {
141:         this.set('Content-Type', setCharset(type, 'utf-8'));
142:       } else {
143:         this.type('html');
144:       }
145:       break;
146:     case 'boolean':
147:     case 'number':
148:     case 'object':
149:       if (chunk === null) {
150:         chunk = '';
151:       } else if (ArrayBuffer.isView(chunk)) {
152:         if (!this.get('Content-Type')) {
153:           this.type('bin');
154:         }
155:       } else {
156:         return this.json(chunk);
157:       }
158:       break;
159:   }
