161:   // determine if ETag should be generated
162:   var etagFn = app.get('etag fn')
163:   var generateETag = !this.get('ETag') && typeof etagFn === 'function'
164: 
165:   var len;
166:   if (chunk !== undefined) {
167:     if (Buffer.isBuffer(chunk)) {
168:       // get length of Buffer
169:       len = chunk.length
170:     } else if (!generateETag && chunk.length < 1000) {
171:       // just calculate length when no ETag + small chunk
172:       len = Buffer.byteLength(chunk, encoding)
173:     } else {
174:       // convert chunk to Buffer and calculate
175:       chunk = Buffer.from(chunk, encoding)
176:       encoding = undefined;
177:       len = chunk.length
178:     }
179: 
180:     // Because Content-Length and Transfer-Encoding can't be present in the response headers together,
181:     // Content-Length should be added only if there is no Transfer-Encoding header
182:     if (!this.get('Transfer-Encoding')) {
183:       this.set('Content-Length', len);
184:     }
185:   }
