 * Wrap the final handler to respond to unmatched requests with a JSON
 * body when the client prefers JSON over HTML.
 *
 * Errors are always passed through to the original handler, so
 * `next(err)` handling is unchanged.
 *
 * @param {Request} req
 * @param {Response} res
 * @param {Function} done
 * @return {Function}
 * @private
 */

function jsonNotFound(req, res, done) {
  return function (err) {
    // unhandled errors, sent responses and clients that do not
    // prefer JSON over HTML keep the default handling
    if (err || res.headersSent || req.accepts(['html', 'json']) !== 'json') {
      return done(err);
    }

    var body = JSON.stringify({
      error: 'Not Found',
      method: req.method,
      path: getResourcePath(req)
    });

    res.statusCode = 404;
    res.setHeader('Content-Type', 'application/json; charset=utf-8');
    res.setHeader('Content-Length', Buffer.byteLength(body, 'utf8'));
    res.end(body, 'utf8');
  };
}

