app.use((req, res, next) => {
  console.log('supertest default accept header:', JSON.stringify(req.headers.accept), '->', req.accepts(['html', 'json']));
  next();
});
request(app).get('/nope').end((e, r) => {
  console.log('default 404:', r.status, r.headers['content-type'], JSON.stringify(r.text).slice(0, 40));
});

