  console.log('json 404:', r.status, r.headers['content-type'], r.text);
});

const sub = express();
sub.get('/ok', (req, res) => res.send('ok'));
const outer = express();
outer.use('/api', sub);
request(outer).get('/api/missing?q=1').set('Accept', 'application/json').end((e, r) => {
  console.log('mounted json 404:', r.status, r.text);
});

request(app).post('/nope').set('Accept', 'application/json').end((e, r) => {
  console.log('post json 404:', r.status, r.text);
});

const errApp = express();
errApp.get('/boom', (req, res, next) => next(new Error('kaboom')));
request(errApp).get('/boom').set('Accept', 'application/json').end((e, r) => {
  console.log('error passthrough:', r.status, r.headers['content-type']);
});

request(app).get('/nope').set('Accept', 'text/html;q=0.5, application/json').end((e, r) => {
  console.log('json preferred:', r.status, r.headers['content-type']);
});

request(app).head('/nope').set('Accept', 'application/json').end((e, r) => {
  console.log('head json 404:', r.status, r.headers['content-type'], r.headers['content-length'], JSON.stringify(r.text));
