 * Sort the keys of `value` alphabetically, returning a new object with the
 * values in the same order as the sorted keys.
 *
 * Used as a JSON replacer, so it is invoked for every value in the tree:
 * non-objects and arrays are returned untouched (keeping array order and
 * letting nested objects be sorted as they are visited).
 *
 * @param {string} key
 * @param {*} value
 * @returns {*}
 * @private
 */

function sortObjectKeys (key, value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return value
  }

  if (value instanceof Number || value instanceof String || value instanceof Boolean) {
    // boxed primitives serialize as their primitive value, a copy would not
    return value
  }

  var keys = Object.keys(value).sort()
  var sorted = Object.create(null)

  for (var i = 0; i < keys.length; i++) {
    sorted[keys[i]] = value[keys[i]]
  }

  return sorted
}

