 * Wrap `replacer` so the value it returns has its object keys sorted
 * alphabetically, keeping the replacer's `this` and arguments intact.
 *
 * @param {function} replacer
 * @returns {function}
 * @private
 */

function sortKeysAndReplace (replacer) {
  return function (key, value) {
    return sortObjectKeys(key, replacer.call(this, key, value))
  }
}

