function sortObjectKeys (key, value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return value
  }
  var keys = Object.keys(value).sort()
  var sorted = Object.create(null)
  for (var i = 0; i < keys.length; i++) {
    sorted[keys[i]] = value[keys[i]]
  }
  return sorted
}
function sortKeysAndReplace (replacer) {
  return function (key, value) {
    return sortObjectKeys.call(this, key, replacer.call(this, key, value))
  }
}
function stringify (value, replacer, spaces, sortKeys) {
  var r = sortKeys
    ? (typeof replacer === 'function' ? sortKeysAndReplace(replacer) : sortObjectKeys)
    : replacer
  return r || spaces ? JSON.stringify(value, r, spaces) : JSON.stringify(value)
}

